"""procurement_core.py - the plumbing of Lab 2.4. You do not edit this file.

It holds everything around your six pieces of lab.py: the gate that every tool call passes (401, 403), the audit log, the HTTP
authentication layer, the helpers that start the server and talk to it with a real MCP client, and the six stage runners.
The server is always started the same safe way: sys.executable plus the absolute path of lab.py, so it does not depend on a shell,
a virtual-environment launcher or the current folder.
"""
import asyncio
import contextlib
import hmac
import json
import logging
import os
import pathlib
import secrets
import socket
import subprocess
import sys
import tempfile
import time
import urllib.error
import urllib.request
from typing import NamedTuple

HERE = pathlib.Path(__file__).resolve().parent
LAB = HERE / "lab.py"
EVIDENCE = HERE / "evidence"
ROLE_ENV = {"analyst": "PROC_KEY_ANALYST", "approver": "PROC_KEY_APPROVER"}
USERS = {"analyst": "dev.analyst", "approver": "maya.approver"}
MASK = "***REDACTED***"
MIN_KEY_LEN = 16
HOOKS = {}  # your pieces, filled in by configure() at the bottom of lab.py
STATE = {"auth": False, "principal": None, "sink": None}  # the server's switches; sink collects audit lines for a stage to inspect


def configure(**hooks):
    HOOKS.update(hooks)


class Principal(NamedTuple):
    user: str
    role: str


class ProcError(Exception):
    """A business-rule failure with a stable machine-readable code, never a stack trace."""

    def __init__(self, code, message, status=None):
        super().__init__(message)
        self.code, self.message, self.status = code, message, status


# ================================================================ server side: results, audit log, gate
def ok(data):
    from mcp.types import CallToolResult, TextContent
    return CallToolResult(content=[TextContent(type="text", text=json.dumps(data, sort_keys=True))], structured_content=data)


def fail(code, message, status=None):
    from mcp.types import CallToolResult, TextContent
    error = {"code": code, "message": message, **({"status": status} if status else {})}
    return CallToolResult(is_error=True, content=[TextContent(type="text", text=json.dumps({"error": error}, sort_keys=True))],
                          structured_content={"error": error})


def audit(event, **fields):
    """One JSON line per event, to stderr (stdout is the protocol channel). YOUR redact() runs on every line."""
    line = HOOKS["redact"](json.dumps({"event": event, **fields}, sort_keys=True, default=str))
    if STATE["sink"] is not None:  # a stage is collecting the lines instead of printing them
        STATE["sink"].append(line)
        return
    sys.stderr.write(line + "\n")
    sys.stderr.flush()


def principal_of(ctx):
    """stdio: the one caller, fixed at startup. HTTP: the principal the auth layer put on this request."""
    if STATE["principal"] is not None:
        return STATE["principal"]
    request = getattr(getattr(ctx, "request_context", None), "request", None)
    return request.scope.get("proc.principal") if request is not None else None


def who(ctx):
    """(user, role) of the caller, or an open-access placeholder while authentication is off."""
    principal = principal_of(ctx)
    return (principal.user, principal.role) if principal else ("open-access", "open")


def run(ctx, tool, work):
    """The gate every tool passes: 401 if nobody, 403 if the role may not call it, else run work() and turn a ProcError into a result."""
    principal = principal_of(ctx)
    if STATE["auth"] and principal is None:
        audit("tool_call", tool=tool, outcome="denied_unauthenticated", role="anonymous")
        return fail("unauthenticated", "No authenticated principal for this call", 401)
    if STATE["auth"] and not HOOKS["is_allowed"](principal.role, tool):
        audit("tool_call", tool=tool, outcome="denied_forbidden", role=principal.role)
        return fail("forbidden", f"Role '{principal.role}' is not permitted to call {tool}", 403)
    try:
        result = ok(work())
        audit("tool_call", tool=tool, outcome="ok", role=who(ctx)[1])
    except ProcError as e:
        result = fail(e.code, e.message, e.status)
        audit("tool_call", tool=tool, outcome=f"error_{e.code}", role=who(ctx)[1])
    return result


# ================================================================ keys
def load_keyring():
    """role -> key, from the environment. Fails closed: no keys, or a short key, and the server refuses to start."""
    ring = {role: os.environ[name] for role, name in ROLE_ENV.items() if os.environ.get(name)}
    if not ring:
        refuse("no PROC_KEY_* variables are set")
    if any(len(key) < MIN_KEY_LEN for key in ring.values()):
        refuse(f"a key is shorter than {MIN_KEY_LEN} characters")
    return ring


def known_secrets():
    """The credential values of THIS process, longest first, so overlapping values are masked completely."""
    names = [*ROLE_ENV.values(), "PROC_API_KEY"]
    return sorted({os.environ[name] for name in names if os.environ.get(name)}, key=len, reverse=True)


def make_keys():
    """Throw-away keys for one stage run. They live in this process and its children, and are never printed or saved."""
    keys = {"analyst": "prk_an_" + secrets.token_urlsafe(18), "approver": "prk_ap_" + secrets.token_urlsafe(18)}
    os.environ.update({ROLE_ENV[role]: key for role, key in keys.items()})
    return keys


def refuse(message):
    print(f"procurement: refusing to start: {message}", file=sys.stderr)
    raise SystemExit(2)


# ================================================================ HTTP authentication layer (ASGI)
def bearer_token(header):
    parts = (header or "").split(None, 1)
    return parts[1].strip() if len(parts) == 2 and parts[0].lower() == "bearer" else ""


class BearerAuthMiddleware:
    """Answer 401 unless your authenticate() accepts the Bearer key. The 401 is identical for every failure."""

    def __init__(self, app):
        self.app = app

    async def __call__(self, scope, receive, send):
        if scope["type"] != "http":  # lifespan must pass through, or the MCP session manager never starts
            return await self.app(scope, receive, send)
        header = {k.decode().lower(): v.decode("latin-1") for k, v in scope["headers"]}.get("authorization", "")
        role = HOOKS["authenticate"](bearer_token(header))
        if role:
            scope["proc.principal"] = Principal(USERS[role], role)
            return await self.app(scope, receive, send)
        audit("auth_failed", authorization=header)  # a debug line, as written while chasing a 401: it holds whatever the caller sent
        body = b'{"error":"unauthorized"}'
        await send({"type": "http.response.start", "status": 401, "headers": [
            (b"content-type", b"application/json"), (b"content-length", str(len(body)).encode()), (b"www-authenticate", b'Bearer realm="procurement"')]})
        await send({"type": "http.response.body", "body": body})


class AccessLogMiddleware:
    """Outermost layer: method, path, status and role of every request. Never headers."""

    def __init__(self, app):
        self.app = app

    async def __call__(self, scope, receive, send):
        if scope["type"] != "http":
            return await self.app(scope, receive, send)
        status = {"code": 0}

        async def send_and_note(message):
            if message["type"] == "http.response.start":
                status["code"] = message["status"]
            await send(message)

        try:
            await self.app(scope, receive, send_and_note)
        finally:
            principal = scope.get("proc.principal")
            audit("http_access", method=scope["method"], path=scope["path"], status=status["code"], role=principal.role if principal else "anonymous")


# ================================================================ starting the server (python lab.py --serve ...)
def use_binary_stdio():
    """On Windows, stop the C runtime from rewriting newlines on the protocol channel."""
    if os.name == "nt":
        import msvcrt
        msvcrt.setmode(sys.stdin.fileno(), os.O_BINARY)
        msvcrt.setmode(sys.stdout.fileno(), os.O_BINARY)


def serve(mcp, args):
    use_binary_stdio()
    HOOKS["setup_logging"]()
    if args.auth == "on":
        load_keyring()
        STATE["auth"] = True
        if args.transport == "stdio":
            role = HOOKS["authenticate"](os.environ.get("PROC_API_KEY", ""))
            if role is None:
                refuse("PROC_API_KEY is missing or not a registered key")
            STATE["principal"] = Principal(USERS[role], role)
    if args.transport == "stdio":
        mcp.run(transport="stdio")
        return
    if not STATE["auth"]:
        refuse("the HTTP transport must run with --auth on")
    import uvicorn
    uvicorn.run(AccessLogMiddleware(BearerAuthMiddleware(mcp.streamable_http_app())), host="127.0.0.1", port=args.port, log_level="warning")


# ================================================================ client side: talk to the server with a real MCP client
def flat(exc):
    """Yield the leaf exceptions of nested exception groups."""
    inner = getattr(exc, "exceptions", None)
    if inner:
        for e in inner:
            yield from flat(e)
    else:
        yield exc


class ClientLog(logging.Handler):
    """Collects what the MCP client logs in this process (it logs JSON-RPC parse errors)."""

    def __init__(self):
        super().__init__(level=logging.DEBUG)
        self.messages = []

    def emit(self, record):
        self.messages.append(record.getMessage())

    def __enter__(self):
        logging.getLogger().addHandler(self)
        return self

    def __exit__(self, *exc):
        logging.getLogger().removeHandler(self)

    @property
    def parse_errors(self):
        return sum("Failed to parse" in m for m in self.messages)


LAST_STDERR = {"text": ""}  # what the last stdio server wrote to stderr: the first place to look when a connection fails


@contextlib.asynccontextmanager
async def stdio_session(auth="off", role=None, init_timeout=8.0):
    """Start `python lab.py --serve` as a stdio MCP server and yield an initialized session."""
    from mcp import ClientSession, StdioServerParameters, stdio_client
    env = {**os.environ, "PYTHONUNBUFFERED": "1", "PYTHONIOENCODING": "utf-8"}
    env.pop("PROC_API_KEY", None)
    if role:
        env["PROC_API_KEY"] = os.environ[ROLE_ENV[role]]
    params = StdioServerParameters(command=sys.executable, args=[str(LAB), "--serve", "--transport", "stdio", "--auth", auth], env=env, cwd=str(HERE))
    with tempfile.TemporaryFile(mode="w+") as errlog:  # a real file: the child needs a handle for its stderr; closed (and deleted) on exit
        try:
            async with stdio_client(params, errlog=errlog) as (read, write):
                async with ClientSession(read, write) as session:
                    await asyncio.wait_for(session.initialize(), timeout=init_timeout)
                    yield session
        finally:
            errlog.seek(0)
            LAST_STDERR["text"] = errlog.read()


@contextlib.asynccontextmanager
async def http_session(url, key=None):
    import httpx2
    from mcp import ClientSession
    from mcp.client.streamable_http import streamable_http_client
    headers = {"Authorization": f"Bearer {key}"} if key else {}
    async with httpx2.AsyncClient(headers=headers, timeout=20.0) as http_client:
        async with streamable_http_client(url, http_client=http_client) as streams:
            async with ClientSession(streams[0], streams[1]) as session:
                await session.initialize()
                yield session


class HttpServer:
    """`with HttpServer() as server:` runs lab.py over streamable HTTP on a free port, and always stops it."""

    def __init__(self):
        s = socket.socket()
        s.bind(("127.0.0.1", 0))
        self.port = s.getsockname()[1]
        s.close()
        self.stderr = tempfile.TemporaryFile(mode="w+b")
        self.proc = None

    @property
    def url(self):
        return f"http://127.0.0.1:{self.port}/mcp"

    def __enter__(self):
        command = [sys.executable, str(LAB), "--serve", "--transport", "http", "--auth", "on", "--port", str(self.port)]
        self.proc = subprocess.Popen(command, cwd=str(HERE), env={**os.environ, "PYTHONUNBUFFERED": "1"}, stdout=subprocess.DEVNULL, stderr=self.stderr)
        try:
            self.wait_until_serving()
        except BaseException:
            self.stop()
            raise
        return self

    def wait_until_serving(self):
        for _ in range(150):
            if self.proc.poll() is not None:
                raise RuntimeError("the server exited early: " + self.log_text()[-300:])
            try:
                urllib.request.urlopen(self.url, timeout=1)
                return
            except urllib.error.HTTPError:
                return  # any HTTP answer, even 401, means the socket is serving
            except OSError:
                time.sleep(0.15)
        raise RuntimeError("the server never became ready")

    def log_text(self):
        self.stderr.flush()
        self.stderr.seek(0)
        return self.stderr.read().decode("utf-8", "replace")

    def stop(self):
        """Stop the process first, close the log handle second, and never fail on cleanup."""
        if self.proc is not None and self.proc.poll() is None:
            self.proc.terminate()
            try:
                self.proc.wait(5)
            except subprocess.TimeoutExpired:
                self.proc.kill()
                self.proc.wait(5)
        with contextlib.suppress(PermissionError, OSError):
            self.stderr.close()

    def __exit__(self, *exc):
        self.stop()
        return False


def raw_status(url, key):
    """The raw HTTP view of a request. The MCP client hides the status of a 401."""
    request = urllib.request.Request(url, headers={"Authorization": f"Bearer {key}"} if key else {})
    try:
        return str(urllib.request.urlopen(request, timeout=5).status)
    except urllib.error.HTTPError as e:
        return f"{e.code} {e.headers.get('WWW-Authenticate')}"


# ================================================================ the six stages
def show(label, good, hint=""):
    print(f"  {'ok  ' if good else 'TODO'}  {label}" + ("" if good else f"   <- {hint}" if hint else ""))
    return good


def save(stage, facts):
    EVIDENCE.mkdir(exist_ok=True)
    (EVIDENCE / f"stage{stage}.json").write_text(json.dumps({"stage": stage, **facts}, indent=1, default=str), encoding="utf-8")


def code_of(result):
    return ((result.structured_content or {}).get("error") or {}).get("code")


def schema_note(result):
    data = result.structured_content or {}
    return data.get("error") or ("rejected by the schema, before our code ran" if result.is_error else {k: data[k] for k in sorted(data) if k in ("id", "count", "status")})


async def stage1():
    print("== Stage 1: a stdio server, and the stdout trap ==")
    facts = {"initialized": False, "parse_errors": 0, "log_lines": 0, "tools": []}
    with ClientLog() as client_log:
        try:
            async with stdio_session() as session:
                facts["tools"] = sorted(t.name for t in (await session.list_tools()).tools)
                found = await asyncio.wait_for(session.call_tool("find_supplier", {"query": "ind"}), 10)
                facts["initialized"], facts["find_supplier_ok"] = True, not found.is_error
        except BaseException as e:  # noqa: BLE001 - the failure is the lesson
            leaf = next(iter(flat(e)))
            print(f"  initialize FAILED ({type(leaf).__name__}): the server answered, but the reply was never parsed")
    facts["parse_errors"] = client_log.parse_errors
    facts["log_lines"] = sum("procurement" in line for line in LAST_STDERR["text"].splitlines())
    show("the client connected and called find_supplier", facts["initialized"],
         "the first thing the server wrote to stdout was not JSON-RPC; read setup_logging (TODO 1)")
    show("the client saw no JSON-RPC parse error", facts["initialized"] and facts["parse_errors"] == 0)
    show("the server's own log lines arrived on stderr", facts["log_lines"] >= 1, "log to sys.stderr, never print")
    if facts["initialized"]:
        print("  tools:", facts["tools"])
    return facts


