    print("== Stage 2: resources ==")
    facts = {"fixed": [], "templates": [], "po_read": False, "bad_id_error": False, "session_alive": False, "supplier_masked": False}
    async with stdio_session() as session:
        facts["fixed"] = sorted(r.uri for r in (await session.list_resources()).resources)
